const body = $input.first().json.body || $input.first().json;

// Campi base
const name = (body.client_name || body.name || body.nome || 'Cliente Privato').trim();
let phone = (body.phone || body.telefono || '').toString().trim();
const city = (body.city || body.citta || 'Bologna').trim();
const serviceType = body.service_type || body.servizio || 'Trasloco Residenziale';
const notes = body.notes || body.messaggio || body.richiesta || '';
const budget = parseFloat(body.estimated_budget || body.budget || 450.0);
const volumeMq = parseInt(body.volume_mq || body.mq || 50);
const source = body.source || body.fonte || 'Web Intake';

// Normalizzazione Telefono Mobile Italiano (+39 3XX XXXXXXX)
let cleanPhone = phone.replace(/[^0-9+]/g, '');
if (cleanPhone.startsWith('0039')) {
  cleanPhone = '+39' + cleanPhone.slice(4);
} else if (cleanPhone.startsWith('39') && cleanPhone.length >= 12) {
  cleanPhone = '+' + cleanPhone;
} else if (cleanPhone.startsWith('3') && cleanPhone.length === 10) {
  cleanPhone = '+39' + cleanPhone;
}

// Verifica sintattica telefono
const phoneRegex = /^\+393\d{8,9}$/;
const isPhoneValid = phoneRegex.test(cleanPhone);

// Filtro Anti-Competitor (ditte, agenzie, P.IVA)
const compKeywords = ['ditta', 'azienda', 'offriamo', 'srl', 's.r.l', 'p.iva', 'partita iva', 'preventivo gratuito', 'personale qualificato', 'flotta'];
const fullText = (name + ' ' + notes + ' ' + serviceType).toLowerCase();
const isCompetitor = compKeywords.some(kw => fullText.includes(kw));

// Intento Cliente
const clientKeywords = ['cerco', 'devo', 'bisogno', 'aiuto', 'sgombero', 'trasloco', 'furgone', 'spostare'];
const hasClientIntent = clientKeywords.some(kw => fullText.includes(kw));

return [{
  json: {
    client_name: name,
    phone: isPhoneValid ? cleanPhone : 'NON_VALIDO',
    is_phone_valid: isPhoneValid,
    is_competitor: isCompetitor,
    has_client_intent: hasClientIntent,
    city: city,
    service_type: serviceType,
    volume_mq: volumeMq,
    estimated_budget: budget,
    source: source,
    notes: notes,
    whatsapp_link: isPhoneValid ? `https://wa.me/${cleanPhone.replace('+', '')}` : ''
  }
}];

